import matplotlib
matplotlib.use("Agg")
from dataclasses import dataclass
import pandas as pd
import seaborn.objects as so
import matplotlib.pyplot as plt

@dataclass
class Trimmed(so.Stat):
    cut: float = 0.1
    def __call__(self, data, groupby, orient, scales):
        other = {"x": "y", "y": "x"}[orient]
        def f(df):
            lo, hi = df[other].quantile([self.cut, 1 - self.cut])
            return pd.DataFrame({orient: [df[orient].iloc[0]],
                                 other: [df[other].clip(lo, hi).mean()]})
        return groupby.apply(data, f)

df = pd.DataFrame({"k": list("aaaaabbb"), "v": [1, 2, 3, 4, 100, 2, 3, 4]})
p = (so.Plot(df, x="k", y="v", color="k").add(so.Bar(), Trimmed(cut=0.2))
       .scale(color=so.Nominal(["C3", "0.6"], order=["b", "a"])))
fig = plt.figure()
p.on(fig).plot()
print([float(round(b.get_height(), 1)) for b in fig.axes[0].patches])  # [6.8, 3.0]
print(df.groupby("k")["v"].mean().round(1).to_dict())  # {'a': 22.0, 'b': 3.0}
